def calculate_S(N):
    S = 0
    K = N + 1
    for a in range(1, N + 1):
        for b in range(1, N + 1):
            S += (a * b) // K
    return S

def calculate_T(N):
    return (N**3 - N**2 + 2) / 4

N_candidates = [3, 7, 11]
for N in N_candidates:
    S_N = calculate_S(N)
    T_N = calculate_T(N)
    print(f"N={N}: S(N)={S_N}, T(N)={T_N}, Match={S_N == T_N}")
